// Inspect archives generated by this project. ZIP64/encrypted archives are unsupported.
const fs=require('fs'),zlib=require('zlib');
module.exports=function entries(file){const b=fs.readFileSync(file);let end=-1;
 for(let i=b.length-22;i>=Math.max(0,b.length-65557);i--)if(b.readUInt32LE(i)===0x06054b50){end=i;break;}
 if(end<0)throw Error('Missing ZIP directory');const count=b.readUInt16LE(end+10),files=new Map();let at=b.readUInt32LE(end+16);
 for(let i=0;i<count;i++){if(b.readUInt32LE(at)!==0x02014b50)throw Error('Invalid ZIP directory');const flags=b.readUInt16LE(at+8),method=b.readUInt16LE(at+10),size=b.readUInt32LE(at+20),plain=b.readUInt32LE(at+24),n=b.readUInt16LE(at+28),extra=b.readUInt16LE(at+30),comment=b.readUInt16LE(at+32),local=b.readUInt32LE(at+42),name=b.subarray(at+46,at+46+n).toString('utf8');if(flags&1||plain>32*1024*1024||files.has(name)||name.includes('..'))throw Error('Unsupported ZIP entry');if(b.readUInt32LE(local)!==0x04034b50)throw Error('Invalid local ZIP entry');const offset=local+30+b.readUInt16LE(local+26)+b.readUInt16LE(local+28),compressed=b.subarray(offset,offset+size);const data=method===0?compressed:method===8?zlib.inflateRawSync(compressed,{maxOutputLength:32*1024*1024}):null;if(!data||data.length!==plain)throw Error('ZIP size mismatch');if(!name.endsWith('/'))files.set(name,data);at+=46+n+extra+comment;}
 return files;
};
